public class ObjectReader__findRootDeserializer_TriageGen0Test {

    private ObjectMapper mapper;
    private DeserializationConfig config;
    private DeserializationContext ctxt;
    private JavaType javaType;
    private JsonDeserializer<Object> mockDeserializer;

    // Accessor class to handle protected method via reflection or subclassing
    private static class TestableObjectReader extends ObjectReader {
        protected TestableObjectReader(ObjectMapper mapper, DeserializationConfig config) {
            super(mapper, config);
        }

        public JsonDeserializer<Object> callFindRootDeserializer(DeserializationContext ctxt, JavaType valueType) 
                throws JsonMappingException {
            return _findRootDeserializer(ctxt, valueType);
        }
    }

    @Before
    public void setUp() {
        mapper = mock(ObjectMapper.class);
        config = mock(DeserializationConfig.class);
        ctxt = mock(DeserializationContext.class);
        javaType = mock(JavaType.class);
        mockDeserializer = mock(JsonDeserializer.class);
    }

    @Test
    public void testFindRootDeserializer_ReturnsExistingRootDeserializer() throws Exception {
        TestableObjectReader reader = new TestableObjectReader(mapper, config);

        // Use reflection to set the private/protected _rootDeserializer field
        Field rootDeserField = ObjectReader.class.getDeclaredField("_rootDeserializer");
        rootDeserField.setAccessible(true);
        rootDeserField.set(reader, mockDeserializer);

        JsonDeserializer<Object> result = reader.callFindRootDeserializer(ctxt, javaType);

        assertEquals(mockDeserializer, result);
        verifyNoInteractions(ctxt);
    }

    @Test(expected = JsonMappingException.class)
    public void testFindRootDeserializer_ThrowsExceptionWhenValueTypeIsNull() throws JsonMappingException {
        TestableObjectReader reader = new TestableObjectReader(mapper, config);
        reader.callFindRootDeserializer(ctxt, null);
    }

    @Test
    public void testFindRootDeserializer_ReturnsFromCache() throws Exception {
        TestableObjectReader reader = new TestableObjectReader(mapper, config);

        // Inject a map into _rootDeserializers
        Field cacheField = ObjectReader.class.getDeclaredField("_rootDeserializers");
        cacheField.setAccessible(true);
        Map<JavaType, JsonDeserializer<Object>> cache = new HashMap<>();
        cache.put(javaType, mockDeserializer);
        cacheField.set(reader, cache);

        JsonDeserializer<Object> result = reader.callFindRootDeserializer(ctxt, javaType);

        assertEquals(mockDeserializer, result);
        verify(ctxt, never()).findRootValueDeserializer(any());
    }

    @Test
    public void testFindRootDeserializer_ResolvesViaContextAndCaches() throws JsonMappingException {
        TestableObjectReader reader = new TestableObjectReader(mapper, config);

        when(ctxt.findRootValueDeserializer(javaType)).thenReturn(mockDeserializer);

        // First call: should resolve via context
        JsonDeserializer<Object> result1 = reader.callFindRootDeserializer(ctxt, javaType);
        assertEquals(mockDeserializer, result1);

        // Second call: should return from cache (verify ctxt is not called again)
        JsonDeserializer<Object> result2 = reader.callFindRootDeserializer(ctxt, javaType);
        assertEquals(mockDeserializer, result2);

        verify(ctxt, times(1)).findRootValueDeserializer(javaType);
    }

    @Test(expected = JsonMappingException.class)
    public void testFindRootDeserializer_ThrowsExceptionWhenContextReturnsNull() throws JsonMappingException {
        TestableObjectReader reader = new TestableObjectReader(mapper, config);

        when(ctxt.findRootValueDeserializer(javaType)).thenReturn(null);

        reader.callFindRootDeserializer(ctxt, javaType);
    }
}
